head.script:
scwin.screenId = "jldfil35300";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goFlashURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.goFlashURL = function (div) {
    /* sdd-asis-lifecycle:begin fn_goFlashURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let goUrl = '/';
    if (div === '11') {
        goUrl = '/submission/searchDisclosureDocument.do?method=searchSubmittedDisclosureDocument';
    } else {
        if (div === '12') {
            goUrl = '/submission/searchDisclosureForm.do?method=findEditClassList';
        } else {
            if (div === '13') {
                goUrl = '/submission/searchDisclosureDocument.do?method=searchSubmittedDisclosureDocument';
            } else {
                if (div === '14') {
                    goUrl = '/submission/searchDisclosureForm.do?method=findEditClassList';
                } else {
                    if (div === '15') {
                        goUrl = '/submission/searchDisclosureDocument.do?method=searchChangeDocument';
                    } else {
                        if (div === '16') {
                            goUrl = '/submission/searchDisclosureDocument.do?method=searchAttachDocument';
                        } else {
                            if (div === '17') {
                                goUrl = '/submission/searchDisclosureDocument.do?method=searchChangeDocument';
                            } else {
                                if (div === '18') {
                                    goUrl = '/submission/searchDisclosureDocument.do?method=searchWritingDocument';
                                } else {
                                    if (div === '19') {
                                        goUrl = '/submission/searchDisclosureDocument.do?method=searchEnglishDocument';
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    $c.win.setPageFrameSrc(null, (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(goUrl));
    /* sdd-asis-lifecycle:end */
};
